// Long-duration playback soak. Fixture clips use the visible frame-ID barcode
// generated by tests/fixtures/generate_media.sh; --natural-media skips only
// those authored-identity/order assertions. Both modes check source-time
// progress, content hashes, drop counters, and timing evidence.

#include <QApplication>
#include <QByteArrayView>
#include <QCommandLineParser>
#include <QCryptographicHash>
#include <QDir>
#include <QElapsedTimer>
#include <QFile>
#include <QImage>
#include <QOpenGLContext>
#include <QOpenGLExtraFunctions>
#include <QScreen>
