namespace {

// ── constants ─────────────────────────────────────────────────────────────

// The pump cadence: fast enough that a 2 s frame gap is measured with four
// samples of its own resolution, slow enough not to add GUI-thread load to a
// run whose whole point is to leave the render path undisturbed.
constexpr int kPumpIntervalMs = 500;
// The frame-order assertion: while the core reports playing-and-not-paused,
// renderedOutputFrames must not stand still for longer than this. Two seconds
// tolerates a slow first fill and one compositor hiccup while still catching
// the multi-second stalls a re-timing burst produces.
constexpr qint64 kMaxFrameGapMs = 2000;
// A fresh source segment gets this long to decode its first frames before the
// soak gives up on it; the smoke waits 8 s for three frames, and a cold
// runner's first decode of a 10-bit HEVC clip is allowed to be slower still.
constexpr qint64 kSegmentStartupGraceMs = 20000;
// A suspiciously identical content hash is re-read after this much wall time
// (several rendered frames at any sane frame rate); still-identical is the
// frozen-picture failure.
constexpr qint64 kSampleRetryDelayMs = 2000;
// Default content-sample period, seconds.
constexpr int kDefaultSampleIntervalSeconds = 30;
// Default drop budget per source segment.
constexpr int kDefaultMaxDrops = 3;
// Default soak length, minutes. The nightly lane asks for 30; the default is
// the cap of what a nightly schedule can afford, so a bare local run makes
// the same claim the canary does.
constexpr double kDefaultMinutes = 30.0;
// Hard ceiling for --minutes: a typo must not park a canary lane for days.
constexpr double kMaxMinutes = 1440.0;
// Slack granted to the requested runtime: the soak stops at the first pump
// tick past the deadline, so only tick cadence plus finishing work can
// overshoot.
constexpr qint64 kRuntimeToleranceMs = 30000;
constexpr qint64 kAudioClockSampleIntervalMs = 5000;
constexpr double kMaxAudioClockSkewSeconds = 1.0;

// ── options ───────────────────────────────────────────────────────────────

struct Options {
    QString media;
    double minutes = kDefaultMinutes;
    double startSeconds = 0.0;
    QString frameTimingLog;
    QString artifactsDirectory;
    int maxDrops = kDefaultMaxDrops;
    int sampleIntervalSeconds = kDefaultSampleIntervalSeconds;
    bool noLoop = false;
    bool naturalMedia = false;
    bool fullscreen = false;
    mplayer::VideoSurface::HdrToneMappingPolicy hdrPolicy =
        mplayer::VideoSurface::HdrToneMappingPolicy::Auto;
    bool requireAudio = false;
};

// A straight byte digest of the grabbed frame. The hash does not have to be
// cryptographic to prove content advanced; SHA-256 is used because the timing
// log is meant to be diffable against any future engine-side frame logger,
// which names the same algorithm.
QString hashFrame(const QImage& frame) {
    if (frame.isNull()) return QString();
    QCryptographicHash digest(QCryptographicHash::Sha256);
    digest.addData(QByteArrayView(reinterpret_cast<const char*>(frame.constBits()),
                                 frame.sizeInBytes()));
    return QString::fromLatin1(digest.result().toHex());
}

// Keep GL row order here; the worker performs the full-frame flip.
QImage readCurrentFramebuffer(mplayer::VideoSurface& surface) {
    if (!surface.context() || QOpenGLContext::currentContext() != surface.context() ||
        surface.width() <= 0 || surface.height() <= 0) {
        return {};
    }
    const qreal dpr = surface.devicePixelRatioF();
    const int width = qRound(surface.width() * dpr);
    const int height = qRound(surface.height() * dpr);
    if (width <= 0 || height <= 0) return {};
    QImage frame(width, height, QImage::Format_RGBA8888);
    if (frame.isNull()) return {};

    QOpenGLExtraFunctions* gl = surface.context()->extraFunctions();
    if (gl == nullptr) return {};
    GLint oldReadFramebuffer = 0;
    GLint oldReadBuffer = 0;
    GLint oldPackAlignment = 4;
    GLint oldPixelPackBuffer = 0;
    gl->glGetIntegerv(GL_READ_FRAMEBUFFER_BINDING, &oldReadFramebuffer);
    gl->glGetIntegerv(GL_READ_BUFFER, &oldReadBuffer);
    gl->glGetIntegerv(GL_PACK_ALIGNMENT, &oldPackAlignment);
    gl->glGetIntegerv(GL_PIXEL_PACK_BUFFER_BINDING, &oldPixelPackBuffer);
    gl->glBindBuffer(GL_PIXEL_PACK_BUFFER, 0);
    gl->glBindFramebuffer(GL_READ_FRAMEBUFFER, surface.defaultFramebufferObject());
    gl->glReadBuffer(GL_COLOR_ATTACHMENT0);
    gl->glPixelStorei(GL_PACK_ALIGNMENT, 1);
    gl->glReadPixels(0, 0, width, height, GL_RGBA, GL_UNSIGNED_BYTE, frame.bits());
    const GLenum readError = gl->glGetError();
    gl->glPixelStorei(GL_PACK_ALIGNMENT, oldPackAlignment);
    gl->glBindBuffer(GL_PIXEL_PACK_BUFFER, static_cast<GLuint>(oldPixelPackBuffer));
    gl->glBindFramebuffer(GL_READ_FRAMEBUFFER, static_cast<GLuint>(oldReadFramebuffer));
    gl->glReadBuffer(static_cast<GLenum>(oldReadBuffer));
    if (readError != GL_NO_ERROR) return {};
    return frame;
}

// No context switching here: this runs inside paintGL, before NoPartialUpdate can discard the FBO.
bool readCenterRgb(mplayer::VideoSurface& surface, std::array<unsigned char, 3>& rgb) {
    if (!surface.context() || QOpenGLContext::currentContext() != surface.context() ||
        surface.width() <= 0 || surface.height() <= 0) {
        return false;
    }
    QOpenGLExtraFunctions* gl = surface.context()->extraFunctions();
    if (gl == nullptr) return false;
    const qreal dpr = surface.devicePixelRatioF();
    const int width = qRound(surface.width() * dpr);
    const int height = qRound(surface.height() * dpr);
    if (width <= 0 || height <= 0) return false;
    const QRect videoRect = mplayer::probes::pictureRect(
        QSize(width, height), surface.videoWidth(), surface.videoHeight());
    if (videoRect.isEmpty()) return false;
    const int x = videoRect.center().x();
    const int y = height - 1 - videoRect.center().y();
    unsigned char pixel[4]{};
    GLint oldReadFramebuffer = 0;
    GLint oldReadBuffer = 0;
    GLint oldPixelPackBuffer = 0;
    gl->glGetIntegerv(GL_READ_FRAMEBUFFER_BINDING, &oldReadFramebuffer);
    gl->glGetIntegerv(GL_READ_BUFFER, &oldReadBuffer);
    gl->glGetIntegerv(GL_PIXEL_PACK_BUFFER_BINDING, &oldPixelPackBuffer);
    gl->glBindBuffer(GL_PIXEL_PACK_BUFFER, 0);
    gl->glBindFramebuffer(GL_READ_FRAMEBUFFER, surface.defaultFramebufferObject());
    gl->glReadBuffer(GL_COLOR_ATTACHMENT0);
    gl->glReadPixels(x, y, 1, 1, GL_RGBA, GL_UNSIGNED_BYTE, pixel);
    const GLenum readError = gl->glGetError();
    gl->glBindBuffer(GL_PIXEL_PACK_BUFFER, static_cast<GLuint>(oldPixelPackBuffer));
    gl->glBindFramebuffer(GL_READ_FRAMEBUFFER, static_cast<GLuint>(oldReadFramebuffer));
    gl->glReadBuffer(static_cast<GLenum>(oldReadBuffer));
    if (readError != GL_NO_ERROR) return false;
    rgb = {pixel[0], pixel[1], pixel[2]};
    return true;
}

bool readFrameIdentity(mplayer::VideoSurface& surface, int& identity) {
    if (!surface.context() || QOpenGLContext::currentContext() != surface.context() ||
        surface.width() <= 0 || surface.height() <= 0) {
        return false;
    }
    QOpenGLExtraFunctions* gl = surface.context()->extraFunctions();
    if (gl == nullptr) return false;
    const qreal dpr = surface.devicePixelRatioF();
    const int width = qRound(surface.width() * dpr);
    const int height = qRound(surface.height() * dpr);
    if (width <= 0 || height <= 0) return false;
    const QRect videoRect = mplayer::probes::pictureRect(
        QSize(width, height), surface.videoWidth(), surface.videoHeight());
    if (videoRect.isEmpty()) return false;
    const int xStart = videoRect.left() + qRound(40.0 * videoRect.width() / 1280.0);
    const int xEnd = videoRect.left() + qRound(208.0 * videoRect.width() / 1280.0);
    const int rowWidth = xEnd - xStart + 1;
    const int sourceY = videoRect.top() + qRound(36.0 * videoRect.height() / 720.0);
    if (rowWidth <= 0 || rowWidth > 1280 || sourceY < 0 || sourceY >= height) return false;

    std::array<unsigned char, 1280 * 4> pixels{};
    GLint oldReadFramebuffer = 0;
    GLint oldReadBuffer = 0;
    GLint oldPackAlignment = 4;
    GLint oldPixelPackBuffer = 0;
    gl->glGetIntegerv(GL_READ_FRAMEBUFFER_BINDING, &oldReadFramebuffer);
    gl->glGetIntegerv(GL_READ_BUFFER, &oldReadBuffer);
    gl->glGetIntegerv(GL_PACK_ALIGNMENT, &oldPackAlignment);
    gl->glGetIntegerv(GL_PIXEL_PACK_BUFFER_BINDING, &oldPixelPackBuffer);
    gl->glBindBuffer(GL_PIXEL_PACK_BUFFER, 0);
    const GLuint widgetFramebuffer = surface.defaultFramebufferObject();
    gl->glBindFramebuffer(GL_READ_FRAMEBUFFER, widgetFramebuffer);
    gl->glReadBuffer(GL_COLOR_ATTACHMENT0);
    gl->glPixelStorei(GL_PACK_ALIGNMENT, 1);
    gl->glReadPixels(xStart, height - 1 - sourceY, rowWidth, 1, GL_RGBA,
                     GL_UNSIGNED_BYTE, pixels.data());
    const GLenum readError = gl->glGetError();
    gl->glPixelStorei(GL_PACK_ALIGNMENT, oldPackAlignment);
    gl->glBindBuffer(GL_PIXEL_PACK_BUFFER, static_cast<GLuint>(oldPixelPackBuffer));
    gl->glBindFramebuffer(GL_READ_FRAMEBUFFER, static_cast<GLuint>(oldReadFramebuffer));
    gl->glReadBuffer(static_cast<GLenum>(oldReadBuffer));
    if (readError != GL_NO_ERROR) return false;

    identity = 0;
    for (int bit = 0; bit < 8; ++bit) {
        const int sourceX = videoRect.left() +
                            qRound((40.0 + bit * 24.0) * videoRect.width() / 1280.0);
        const int offset = (sourceX - xStart) * 4;
        const int gray = (11 * pixels[offset] + 16 * pixels[offset + 1] +
                          5 * pixels[offset + 2]) / 32;
        if (gray >= 112) identity |= (1 << bit);
    }
    return true;
}

class ProbeVideoSurface final : public mplayer::VideoSurface {
public:
    using mplayer::VideoSurface::VideoSurface;

    std::function<void()> afterPaint;

protected:
    void paintGL() override {
        mplayer::VideoSurface::paintGL();
        if (afterPaint) afterPaint();
    }
};

// One source segment's drop accounting. Baselines are read at the segment's
// first live tick and compared against the reading at its end, because mpv's
// drop counters travel with the file load: a lifetime cumulative reading would
// either reset under the loops (making a soak of N replays unassertable) or
// accumulate over legitimately clean loops.
struct DropDelta {
    int segment = 0;
    std::optional<int64_t> decoder;
    std::optional<int64_t> vo;
};

// Drop baselines can arrive after playback starts: diagnostics are populated
// by asynchronous property replies, so the first live tick may be unknown.
struct SegmentAccounting {
    bool videoSeen = false;
    qint64 becameLiveAtMs = 0;
    quint64 renderedBaseline = 0;
    quint64 lastRendered = 0;
    qint64 lastAdvanceAtMs = 0;
    double lastSourcePosition = -1.0;
    qint64 lastSourceProgressAtMs = 0;
    int lastFrameIdentity = -1;
    qint64 lastIdentityAtMs = 0;
    qint64 lastIdentityAdvanceAtMs = 0;
    std::optional<int64_t> decoderAtLive;
    std::optional<int64_t> voAtLive;
    std::optional<int64_t> decoderLast;
    std::optional<int64_t> voLast;
};

struct HashedContentSample {
    QString hash;
    QImage framebuffer;
    int segment = 0;
    uint64_t epoch = 0;
    bool isRetry = false;
    double sourcePosition = 0.0;
    qint64 capturedAtMs = 0;
    qint64 captureElapsedUs = 0;
    qint64 flipElapsedUs = 0;
    qint64 hashElapsedUs = 0;
};

// ── the soak machine ──────────────────────────────────────────────────────

class Soak {
public:
    Soak(const Options& options, QApplication& app) : options_(options), app_(app) {}

    int run();

private:
    // What one content sample concluded. Deferred means the sampler read
    // nothing judgeable (not playing, or no frame) and wants to try again on
    // the next tick without advancing its schedule.
    enum class SampleOutcome { Deferred, Advanced, Identical };

    SampleOutcome sampleContent(const QString& hash, const QImage& framebuffer, bool isRetry,
                                double sourcePosition, qint64 capturedAtMs);
    void requestContentSample(bool isRetry);
    void processCapturedContentSample();
    void pollContentHash();
    void processContentHashResult(HashedContentSample result);
    void onSurfacePainted();
    void tick();
    void onMediaEnded();
    void onFrameSwapped();
    void sampleAudioClock(qint64 nowMs);
    void armSafetyDeadline();
    void recordDropObservations(const mplayer::PlaybackDiagnostics& diagnostics);
    void failAndFinish(const QString& reason);
    void finish();
    void recordTimingLine(const QString& line);

    const Options& options_;
    QApplication& app_;

    // A QWidget member must be constructed after QApplication exists; Soak is
    // only ever built in main() after the application object.
    ProbeVideoSurface surface_;
    QElapsedTimer wall_;
    QElapsedTimer segmentStartClock_;

    mplayer::probes::Verdict verdict_;

    QString mediaError_;
    int mediaErrorCount_ = 0;
    bool finished_ = false;
    bool startSeekIssued_ = false;
    bool startPositionReady_ = false;
    bool safetyDeadlineArmed_ = false;
    double actualStartPosition_ = -1.0;
    qint64 startSeekAtMs_ = 0;
    bool reopenQueued_ = false;
    qint64 notPlayingSinceMs_ = -1;
    int segmentIndex_ = 0;

    SegmentAccounting segment_;
    std::vector<DropDelta> dropDeltas_;

    QString previousHash_;
    qint64 nextSampleAtMs = 0;
    quint64 identityReadbacks_ = 0;
    quint64 naturalCenterReadbacks_ = 0;
    quint64 naturalBlackSamples_ = 0;
    qint64 nextNaturalCenterLogAtMs_ = 0;
    bool previousNaturalBlack_ = false;
    quint64 lastIdentityRenderSerial_ = 0;
    quint64 lastIdentityCaptureSerial_ = 0;
    quint64 cachedBarcodeSerial_ = 0;
    uint64_t cachedBarcodeEpoch_ = 0;
    int cachedBarcodeIdentity_ = -1;
    bool cachedBarcodeRead_ = false;
    quint64 readbackTotalUs_ = 0;
    quint64 readbackMaxUs_ = 0;
    qint64 maxInterSwapGapMs_ = 0;
    qint64 nextAudioClockSampleAtMs_ = 0;
    int audioClockSamples_ = 0;
    bool audioRuntimeLogged_ = false;
    int audioSampleRate_ = 0;
    int audioTrackId_ = 0;
    double lastAudioPts_ = -1.0;
    bool audioPtsProgressed_ = false;
    bool audioProbeBusy_ = false;
    bool hasIdentityRenderSerial_ = false;
    bool sampleRetryPending_ = false;
    bool contentCaptureRequested_ = false;
    bool contentSampleInFlight_ = false;
    bool contentCaptureIsRetry_ = false;
    bool pendingContentIsRetry_ = false;
    int pendingContentSegment_ = -1;
    uint64_t pendingContentEpoch_ = 0;
    QImage pendingContentFrame_;
    qint64 pendingContentCapturedAtMs_ = 0;
    double pendingContentSourcePosition_ = 0.0;
    qint64 pendingContentCaptureElapsedUs_ = 0;
    qint64 sampleRetryAtMs = 0;
    std::future<HashedContentSample> contentHashFuture_;
    int     samplesTaken_ = 0;
    int frozenHashFailures_ = 0;

    std::unique_ptr<QFile> timingLog_;
    bool timingLogFailed_ = false;
    bool timingLogClosed_ = false;
    QImage firstArtifactFrame_;
    QImage lastArtifactFrame_;
    QImage screenArtifactFrame_;
    bool screenCaptureUnavailable_ = false;
    bool artifactWriteFailed_ = false;
    QTimer pump_;
};

void Soak::armSafetyDeadline() {
    if (safetyDeadlineArmed_) return;
    safetyDeadlineArmed_ = true;
    const int safetyDeadlineMs =
        static_cast<int>(options_.minutes * 60.0 * 1000.0) + static_cast<int>(kRuntimeToleranceMs);
    QTimer::singleShot(safetyDeadlineMs, &surface_, [this]() {
        if (!finished_) failAndFinish(QStringLiteral("the safety deadline elapsed"));
    });
}

void Soak::recordTimingLine(const QString& line) {
    if (!timingLog_ || timingLogClosed_ || timingLogFailed_) return;
    const QByteArray bytes = line.toUtf8() + '\n';
    if (timingLog_->write(bytes) != bytes.size()) {
        timingLogFailed_ = true;
        std::fprintf(stderr, "frame_order_soak: timing evidence write failed (%s)\n",
                     qPrintable(timingLog_->errorString()));
    }
}

void Soak::recordDropObservations(const mplayer::PlaybackDiagnostics& diagnostics) {
    if (!segment_.decoderAtLive && diagnostics.decoderDropCount) {
        segment_.decoderAtLive = diagnostics.decoderDropCount;
    }
    if (!segment_.voAtLive && diagnostics.voDropCount) {
        segment_.voAtLive = diagnostics.voDropCount;
    }
    if (diagnostics.decoderDropCount) segment_.decoderLast = diagnostics.decoderDropCount;
    if (diagnostics.voDropCount) segment_.voLast = diagnostics.voDropCount;
}

void Soak::sampleAudioClock(qint64 nowMs) {
    if (!options_.requireAudio || audioProbeBusy_ || nowMs < nextAudioClockSampleAtMs_) return;
    audioProbeBusy_ = true;
    const auto track = surface_.probeMpvProperty(QStringLiteral("aid"),
                                                  mplayer::ProbePropertyKind::Number);
    const auto rate = surface_.probeMpvProperty(QStringLiteral("audio-params/samplerate"),
                                                 mplayer::ProbePropertyKind::Number);
    const auto audioPts = surface_.probeMpvProperty(QStringLiteral("audio-pts"),
                                                     mplayer::ProbePropertyKind::Number);
    const auto avsync = surface_.probeMpvProperty(QStringLiteral("avsync"),
                                                  mplayer::ProbePropertyKind::Number);
    const auto currentAo = surface_.probeMpvProperty(QStringLiteral("current-ao"),
                                                      mplayer::ProbePropertyKind::Text);
    audioProbeBusy_ = false;
    if (finished_) return;
    nextAudioClockSampleAtMs_ = wall_.elapsed() + kAudioClockSampleIntervalMs;
    if (!audioRuntimeLogged_) {
        audioRuntimeLogged_ = true;
        const auto version = surface_.probeMpvProperty(QStringLiteral("mpv-version"),
                                                        mplayer::ProbePropertyKind::Text);
        if (finished_) return;
        recordTimingLine(QStringLiteral("audio_runtime mpv_version=%1")
                             .arg(version &&
                                          version->kind == mplayer::ProbePropertyValue::Kind::Text
                                      ? version->text
                                      : QStringLiteral("unavailable")));
    }
    const auto numberOrUnavailable = [](const std::optional<mplayer::ProbePropertyValue>& value) {
        return value && value->isNumeric()
                   ? QString::number(value->asNumber(), 'f', 3)
                   : QStringLiteral("unavailable");
    };
    const QString aoName = currentAo &&
                                   currentAo->kind == mplayer::ProbePropertyValue::Kind::Text
                               ? currentAo->text
                               : QStringLiteral("unavailable");
    recordTimingLine(QStringLiteral("audio_observation elapsed_ms=%1 aid=%2 sample_rate=%3 "
                                    "audio_pts_s=%4 avsync_s=%5 current_ao=%6")
                         .arg(wall_.elapsed())
                         .arg(numberOrUnavailable(track))
                         .arg(numberOrUnavailable(rate))
                         .arg(numberOrUnavailable(audioPts))
                         .arg(numberOrUnavailable(avsync))
                         .arg(aoName));
    if (!track || !track->isNumeric() || track->asNumber() <= 0.0 ||
        !rate || !rate->isNumeric() || rate->asNumber() <= 0.0 ||
        !audioPts || !audioPts->isNumeric() || !std::isfinite(audioPts->asNumber())) {
        return;
    }
    audioTrackId_ = static_cast<int>(track->asNumber());
    audioSampleRate_ = static_cast<int>(rate->asNumber());
    if (lastAudioPts_ >= 0.0 && audioPts->asNumber() > lastAudioPts_ + 0.02) {
        audioPtsProgressed_ = true;
    }
    lastAudioPts_ = audioPts->asNumber();
    const double skew = std::abs(audioPts->asNumber() - surface_.position());
    ++audioClockSamples_;
    verdict_.require(skew <= kMaxAudioClockSkewSeconds,
                     QStringLiteral("audio PTS stays within %1 s of mpv time-pos (skew %2 s)")
                         .arg(kMaxAudioClockSkewSeconds, 0, 'f', 1)
                         .arg(skew, 0, 'f', 3));
    recordTimingLine(QStringLiteral("audio_clock elapsed_ms=%1 audio_pts_s=%2 source_time_s=%3 "
                                    "skew_s=%4 sample_rate=%5 track_id=%6 progressed=%7")
                         .arg(wall_.elapsed())
                         .arg(audioPts->asNumber(), 0, 'f', 3)
                         .arg(surface_.position(), 0, 'f', 3)
                         .arg(skew, 0, 'f', 3)
                         .arg(audioSampleRate_)
                         .arg(audioTrackId_)
                         .arg(int(audioPtsProgressed_)));
}

void Soak::onSurfacePainted() {
    if (finished_ || !segment_.videoSeen || !surface_.hasVideo() ||
        !surface_.isPlaying() || surface_.pauseObserved()) {
        return;
    }
    if (options_.naturalMedia) {
        if (!options_.frameTimingLog.isEmpty()) {
            std::array<unsigned char, 3> rgb{};
            if (readCenterRgb(surface_, rgb)) {
                ++naturalCenterReadbacks_;
                const int luma = (11 * rgb[0] + 16 * rgb[1] + 5 * rgb[2]) / 32;
                const bool blackCandidate = luma <= 4;
                const qint64 nowMs = wall_.elapsed();
                if (blackCandidate) ++naturalBlackSamples_;
                if (blackCandidate != previousNaturalBlack_ ||
                    nowMs >= nextNaturalCenterLogAtMs_) {
                    recordTimingLine(QStringLiteral(
                                         "natural_center elapsed_ms=%1 source_time_s=%2 "
                                         "render_serial=%3 rgb=%4,%5,%6 luma=%7 "
                                         "black_candidate=%8")
                                         .arg(nowMs)
                                         .arg(surface_.position(), 0, 'f', 3)
                                         .arg(static_cast<qulonglong>(
                                             surface_.playbackDiagnostics().renderedOutputFrames))
                                         .arg(rgb[0])
                                         .arg(rgb[1])
                                         .arg(rgb[2])
                                         .arg(luma)
                                         .arg(int(blackCandidate)));
                    nextNaturalCenterLogAtMs_ = nowMs + 1000;
                }
                previousNaturalBlack_ = blackCandidate;
            }
        }
    } else {
        const quint64 renderSerial = surface_.playbackDiagnostics().renderedOutputFrames;
        if (renderSerial == 0 || renderSerial == lastIdentityCaptureSerial_) return;
        lastIdentityCaptureSerial_ = renderSerial;
        cachedBarcodeSerial_ = renderSerial;
        cachedBarcodeEpoch_ = surface_.sourceEpoch();
        QElapsedTimer readbackClock;
        readbackClock.start();
        int identity = -1;
        cachedBarcodeRead_ = readFrameIdentity(surface_, identity);
        if (cachedBarcodeRead_) cachedBarcodeIdentity_ = identity;
        const quint64 costUs =
            static_cast<quint64>(std::max<qint64>(0, readbackClock.nsecsElapsed() / 1000));
        ++identityReadbacks_;
        readbackTotalUs_ += costUs;
        readbackMaxUs_ = std::max(readbackMaxUs_, costUs);
    }

    if (!contentCaptureRequested_) return;
    QElapsedTimer contentCaptureClock;
    if (timingLog_) contentCaptureClock.start();
    const QImage framebuffer = readCurrentFramebuffer(surface_);
    if (framebuffer.isNull()) {
        contentCaptureRequested_ = false;
        contentSampleInFlight_ = false;
        verdict_.require(false,
                         QStringLiteral("content-sample framebuffer read succeeded during paint"));
        recordTimingLine(QStringLiteral("content_sample elapsed_ms=%1 framebuffer=unavailable")
                             .arg(wall_.elapsed()));
        return;
    }
    pendingContentFrame_ = framebuffer;
    pendingContentIsRetry_ = contentCaptureIsRetry_;
    pendingContentSegment_ = segmentIndex_;
    pendingContentEpoch_ = surface_.sourceEpoch();
    pendingContentCapturedAtMs_ = wall_.elapsed();
    pendingContentSourcePosition_ = surface_.position();
    pendingContentCaptureElapsedUs_ =
        timingLog_ ? contentCaptureClock.nsecsElapsed() / 1000 : 0;
    if (timingLog_) {
        recordTimingLine(QStringLiteral("content_capture elapsed_ms=%1 source_time_s=%2 "
                                        "capture_us=%3 pixels=%4x%5")
                             .arg(pendingContentCapturedAtMs_)
                             .arg(pendingContentSourcePosition_, 0, 'f', 3)
                             .arg(pendingContentCaptureElapsedUs_)
                             .arg(framebuffer.width())
                             .arg(framebuffer.height()));
    }
    contentCaptureRequested_ = false;
    QTimer::singleShot(0, &surface_, [this]() { processCapturedContentSample(); });
}

void Soak::onFrameSwapped() {
    if (finished_ || !segment_.videoSeen || !surface_.hasVideo() ||
        !surface_.isPlaying() || surface_.pauseObserved()) return;
    const quint64 renderSerial = surface_.playbackDiagnostics().renderedOutputFrames;
    if (renderSerial == 0 ||
        (hasIdentityRenderSerial_ && renderSerial == lastIdentityRenderSerial_)) {
        return;
    }
    hasIdentityRenderSerial_ = true;
    lastIdentityRenderSerial_ = renderSerial;
    const qint64 swapAtMs = wall_.elapsed();
    const qint64 interSwapGapMs = swapAtMs - segment_.lastIdentityAtMs;
    if (interSwapGapMs >= 0) {
        maxInterSwapGapMs_ = std::max(maxInterSwapGapMs_, interSwapGapMs);
        if (interSwapGapMs > kMaxFrameGapMs) {
            verdict_.require(false,
                             QStringLiteral("rendered output-frame swaps were %1 ms apart "
                                            "(maximum %2 ms)")
                                 .arg(interSwapGapMs)
                                 .arg(kMaxFrameGapMs));
        }
    }
    segment_.lastIdentityAtMs = swapAtMs;
    if (options_.naturalMedia) return;
    if (!cachedBarcodeRead_ || cachedBarcodeSerial_ != renderSerial ||
        cachedBarcodeEpoch_ != surface_.sourceEpoch()) {
        verdict_.require(false,
                         QStringLiteral("displayed frame identity was captured during paint "
                                        "for the swapped output frame and source"));
        return;
    }
    const int identity = cachedBarcodeIdentity_;
    const qint64 nowMs = swapAtMs;
    if (segment_.lastFrameIdentity >= 0) {
        const int forward = (identity - segment_.lastFrameIdentity + 256) % 256;
        if (forward > 128) {
            verdict_.require(false,
                             QStringLiteral("displayed frame identity moved backwards "
                                            "(%1 -> %2, segment %3, source time %4 s)")
                                 .arg(segment_.lastFrameIdentity)
                                 .arg(identity)
                                 .arg(segmentIndex_)
                                 .arg(surface_.position(), 0, 'f', 3));
        }
        if (identity != segment_.lastFrameIdentity) {
            segment_.lastIdentityAdvanceAtMs = nowMs;
        } else if (nowMs - segment_.lastIdentityAdvanceAtMs > kMaxFrameGapMs + 2500) {
            verdict_.require(false,
                             QStringLiteral("displayed frame identity %1 stayed unchanged "
                                            "for %2 s while source time was %3 s")
                                 .arg(identity)
                                 .arg((nowMs - segment_.lastIdentityAdvanceAtMs) / 1000.0, 0, 'f', 1)
                                 .arg(surface_.position(), 0, 'f', 3));
            segment_.lastIdentityAdvanceAtMs = nowMs;
        }
    }
    segment_.lastFrameIdentity = identity;

    if (identityReadbacks_ % 120 == 0) {
        recordTimingLine(QStringLiteral("display elapsed_ms=%1 source_time_s=%2 frame_id=%3 "
                                        "render_serial=%4 source_epoch=%5 readbacks=%6 "
                                        "readback_total_us=%7 readback_max_us=%8")
                             .arg(nowMs)
                             .arg(surface_.position(), 0, 'f', 3)
                             .arg(identity)
                             .arg(static_cast<qulonglong>(cachedBarcodeSerial_))
                             .arg(static_cast<qulonglong>(cachedBarcodeEpoch_))
                             .arg(static_cast<qulonglong>(identityReadbacks_))
                             .arg(static_cast<qulonglong>(readbackTotalUs_))
                             .arg(static_cast<qulonglong>(readbackMaxUs_)));
    }
}

void Soak::requestContentSample(bool isRetry) {
    if (!surface_.hasVideo() || !surface_.isPlaying() || surface_.pauseObserved() ||
        contentSampleInFlight_) {
        return;
    }
    contentSampleInFlight_ = true;
    contentCaptureRequested_ = true;
    contentCaptureIsRetry_ = isRetry;
}

void Soak::processCapturedContentSample() {
    if (finished_) return;
    if (pendingContentFrame_.isNull() || pendingContentSegment_ != segmentIndex_ ||
        pendingContentEpoch_ != surface_.sourceEpoch()) {
        pendingContentFrame_ = {};
        contentSampleInFlight_ = false;
        return;
    }
    const bool isRetry = pendingContentIsRetry_;
    const int segment = pendingContentSegment_;
    const uint64_t epoch = pendingContentEpoch_;
    const qint64 capturedAtMs = pendingContentCapturedAtMs_;
    const double sourcePosition = pendingContentSourcePosition_;
    const qint64 captureElapsedUs = pendingContentCaptureElapsedUs_;
    const bool collectTimings = timingLog_ != nullptr;
    QImage framebuffer = std::move(pendingContentFrame_);
    try {
        contentHashFuture_ = std::async(
            std::launch::async,
            [framebuffer = std::move(framebuffer), segment, epoch, isRetry, capturedAtMs,
             captureElapsedUs, collectTimings, sourcePosition]() mutable {
                QElapsedTimer flipClock;
                qint64 flipElapsedUs = 0;
                if (collectTimings) flipClock.start();
                framebuffer = framebuffer.flipped(Qt::Vertical);
                if (collectTimings) flipElapsedUs = flipClock.nsecsElapsed() / 1000;
                QElapsedTimer hashClock;
                qint64 hashElapsedUs = 0;
                if (collectTimings) hashClock.start();
                const QRect contentRect(framebuffer.width() / 8, framebuffer.height() / 8,
                                        framebuffer.width() * 3 / 4,
                                        framebuffer.height() * 3 / 4);
                const QString hash = hashFrame(framebuffer.copy(contentRect));
                if (collectTimings) hashElapsedUs = hashClock.nsecsElapsed() / 1000;
                return HashedContentSample{hash,
                                           std::move(framebuffer),
                                           segment,
                                           epoch,
                                           isRetry,
                                           sourcePosition,
                                           capturedAtMs,
                                           captureElapsedUs,
                                           flipElapsedUs,
                                           hashElapsedUs};
            });
    } catch (const std::exception& error) {
        contentSampleInFlight_ = false;
        verdict_.require(false,
                         QStringLiteral("content hash worker started (%1)")
                             .arg(QString::fromLocal8Bit(error.what())));
    }
}

void Soak::pollContentHash() {
    if (!contentHashFuture_.valid() ||
        contentHashFuture_.wait_for(std::chrono::milliseconds(0)) != std::future_status::ready) {
        return;
    }
    try {
        processContentHashResult(contentHashFuture_.get());
    } catch (const std::exception& error) {
        contentSampleInFlight_ = false;
        verdict_.require(false,
                         QStringLiteral("content hash worker completed (%1)")
                             .arg(QString::fromLocal8Bit(error.what())));
    }
}

void Soak::processContentHashResult(HashedContentSample result) {
    contentSampleInFlight_ = false;
    if (result.segment != segmentIndex_ || result.epoch != surface_.sourceEpoch()) return;
    if (timingLog_) {
        recordTimingLine(QStringLiteral("content_hash capture_elapsed_ms=%1 source_time_s=%2 "
                                        "capture_us=%3 flip_us=%4 hash_elapsed_us=%5 bytes=%6")
                             .arg(result.capturedAtMs)
                             .arg(result.sourcePosition, 0, 'f', 3)
                             .arg(result.captureElapsedUs)
                             .arg(result.flipElapsedUs)
                             .arg(result.hashElapsedUs)
                             .arg(static_cast<qulonglong>(result.framebuffer.sizeInBytes())));
    }
    const SampleOutcome outcome = sampleContent(result.hash, result.framebuffer, result.isRetry,
                                                result.sourcePosition, result.capturedAtMs);
    if (finished_) return;
    if (result.isRetry) {
        if (outcome == SampleOutcome::Advanced) sampleRetryPending_ = false;
        if (!sampleRetryPending_) {
            nextSampleAtMs = result.capturedAtMs +
                             static_cast<qint64>(options_.sampleIntervalSeconds) * 1000;
        }
    } else if (outcome != SampleOutcome::Deferred) {
        nextSampleAtMs = result.capturedAtMs +
                         static_cast<qint64>(options_.sampleIntervalSeconds) * 1000;
    }
}

Soak::SampleOutcome Soak::sampleContent(const QString& hash, const QImage& framebuffer,
                                        bool isRetry, double sourcePosition,
                                        qint64 capturedAtMs) {
    if (hash.isEmpty()) return SampleOutcome::Deferred;
    if (!options_.artifactsDirectory.isEmpty()) {
        if (firstArtifactFrame_.isNull()) firstArtifactFrame_ = framebuffer;
        lastArtifactFrame_ = framebuffer;
    }

    if (previousHash_.isEmpty()) {
        // First sample of a segment: the baseline the next sample is judged
        // against. It records; it cannot fail.
        previousHash_ = hash;
        ++samplesTaken_;
        std::fprintf(stderr, "sample %d at %lld ms: %s (baseline)\n", samplesTaken_,
                     static_cast<long long>(capturedAtMs), qPrintable(hash));
        recordTimingLine(QStringLiteral("sample elapsed_ms=%1 hash=%2 baseline")
                             .arg(capturedAtMs)
                             .arg(hash));
        return SampleOutcome::Advanced;
    }
    if (hash != previousHash_) {
        previousHash_ = hash;
        ++samplesTaken_;
        std::fprintf(stderr, "sample %d at %lld ms: %s (advanced)\n", samplesTaken_,
                     static_cast<long long>(capturedAtMs), qPrintable(hash));
        recordTimingLine(QStringLiteral("sample elapsed_ms=%1 hash=%2 advanced=yes")
                             .arg(capturedAtMs)
                             .arg(hash));
        return SampleOutcome::Advanced;
    }
    if (!isRetry) {
        // Identical content at one instant is not a failure yet: the grab can
        // land on two visually-equal quantized frames of a very slow gradient.
        // Wait for more rendered frames and read again; only a hash that
        // refuses to move while frames keep rendering is a frozen picture.
        sampleRetryPending_ = true;
        sampleRetryAtMs = capturedAtMs + kSampleRetryDelayMs;
        return SampleOutcome::Identical;
    }
    // Still identical after fresh frames rendered: the sequence froze, which
    // is the buffered-past-frame signature this probe exists to catch.
    ++samplesTaken_;
    ++frozenHashFailures_;
    sampleRetryPending_ = false;
    previousHash_ = hash;
    verdict_.require(false,
                     QStringLiteral("the frame-content hash did not advance between samples "
                                    "%1 and %2 (position %3 s)")
                         .arg(samplesTaken_ - 1)
                         .arg(samplesTaken_)
                         .arg(sourcePosition, 0, 'f', 3));
    recordTimingLine(QStringLiteral("sample elapsed_ms=%1 hash=%2 advanced=NO")
                         .arg(capturedAtMs)
                         .arg(hash));
    return SampleOutcome::Identical;
}

void Soak::onMediaEnded() {
    if (finished_) return;
    if (options_.noLoop) {
        failAndFinish(QStringLiteral("continuous-source acceptance input reached EOF"));
        return;
    }
    // Finalize this segment's drop reading while the ending file is still the
    // loaded one - after a reopen the counters belong to the next file.
    const mplayer::PlaybackDiagnostics diagnostics = surface_.playbackDiagnostics();
    recordDropObservations(diagnostics);
    DropDelta delta;
    delta.segment = segmentIndex_;
    if (segment_.decoderAtLive.has_value() && segment_.decoderLast.has_value()) {
        delta.decoder = *segment_.decoderLast - *segment_.decoderAtLive;
    }
    if (segment_.voAtLive.has_value() && segment_.voLast.has_value()) {
        delta.vo = *segment_.voLast - *segment_.voAtLive;
    }
    dropDeltas_.push_back(delta);
    verdict_.metric(QStringLiteral("segment %1: wall %2 s, ended at position %3 s, "
                                    "decoder drops %4, vo drops %5")
                        .arg(segmentIndex_)
                        .arg((wall_.elapsed() - segment_.becameLiveAtMs) / 1000.0, 0, 'f', 1)
                        .arg(surface_.position(), 0, 'f', 3)
                        .arg(delta.decoder.has_value()
                                 ? QString::number(static_cast<long long>(*delta.decoder))
                                 : QStringLiteral("unavailable"))
                        .arg(delta.vo.has_value()
                                 ? QString::number(static_cast<long long>(*delta.vo))
                                 : QStringLiteral("unavailable")));
    recordTimingLine(QStringLiteral("segment_end segment=%1 decoder_drops=%2 vo_drops=%3")
                         .arg(segmentIndex_)
                         .arg(delta.decoder.has_value()
                                  ? QString::number(static_cast<long long>(*delta.decoder))
                                  : QStringLiteral("unavailable"))
                         .arg(delta.vo.has_value()
                                  ? QString::number(static_cast<long long>(*delta.vo))
                                  : QStringLiteral("unavailable")));
    // A finite clip inside a long soak restarts; each reopen is a fresh file
    // load with fresh counters, which is what the per-segment deltas above
    // are for. The pump services the reopen on its own tick, never inside
    // this emission, so the surface is never asked to load a file while its
    // own end-of-file handling is still running.
    reopenQueued_ = true;
}

void Soak::failAndFinish(const QString& reason) {
    if (finished_) return;
    verdict_.require(false, reason);
    finish();
}

void Soak::finish() {
    if (finished_) return;
    finished_ = true;
    pump_.stop();
    surface_.setPaused(true);
    const mplayer::PlaybackDiagnostics diagnostics = surface_.playbackDiagnostics();
    const qint64 elapsedMs = wall_.elapsed();
    if (contentHashFuture_.valid()) {
        contentHashFuture_.wait();
        try {
            processContentHashResult(contentHashFuture_.get());
        } catch (const std::exception& error) {
            contentSampleInFlight_ = false;
            verdict_.require(false,
                             QStringLiteral("content hash worker completed during shutdown (%1)")
                                 .arg(QString::fromLocal8Bit(error.what())));
        }
    }

    const qint64 requestedMs = static_cast<qint64>(options_.minutes * 60.0 * 1000.0);
    verdict_.metric(QStringLiteral("requested start %1 s, actual start %2 s")
                        .arg(options_.startSeconds, 0, 'f', 3)
                        .arg(actualStartPosition_, 0, 'f', 3));
    if (segment_.videoSeen) {
        const qint64 trailingGapMs = elapsedMs - segment_.lastIdentityAtMs;
        if (trailingGapMs >= 0) {
            maxInterSwapGapMs_ = std::max(maxInterSwapGapMs_, trailingGapMs);
            if (trailingGapMs > kMaxFrameGapMs) {
                verdict_.require(false,
                                 QStringLiteral("no new rendered output-frame swap for %1 ms "
                                                "at finish (maximum %2 ms)")
                                     .arg(trailingGapMs)
                                     .arg(kMaxFrameGapMs));
            }
        }
    }

    // (d) the requested runtime is the clock the whole soak is judged on.
    verdict_.metric(QStringLiteral("soak ended after %1 s of the requested %2 s")
                        .arg(elapsedMs / 1000.0, 0, 'f', 1)
                        .arg(requestedMs / 1000.0, 0, 'f', 0));
    verdict_.require(elapsedMs >= requestedMs &&
                         elapsedMs - requestedMs <= kRuntimeToleranceMs,
                     QStringLiteral("the soak honored its requested runtime (elapsed %1 s, "
                                    "requested %2 s)")
                         .arg(elapsedMs / 1000.0, 0, 'f', 1)
                         .arg(requestedMs / 1000.0, 0, 'f', 0));

    verdict_.require(mediaErrorCount_ == 0,
                     QStringLiteral("the soak reported no media error (last: %1)")
                         .arg(mediaError_.isEmpty() ? QStringLiteral("none") : mediaError_));

    // The closing segment's drops: a segment ended by the deadline, not by
    // EOF, is finalized here; EOF-ended segments were finalized in
    // onMediaEnded().
    if (segment_.videoSeen) {
        recordDropObservations(diagnostics);
        DropDelta delta;
        delta.segment = segmentIndex_;
        if (segment_.decoderAtLive.has_value() && segment_.decoderLast.has_value()) {
            delta.decoder = *segment_.decoderLast - *segment_.decoderAtLive;
        }
        if (segment_.voAtLive.has_value() && segment_.voLast.has_value()) {
            delta.vo = *segment_.voLast - *segment_.voAtLive;
        }
        dropDeltas_.push_back(delta);
    }

    const qint64 contentCoverageWindowMs =
        static_cast<qint64>(options_.sampleIntervalSeconds) * 1000 + kSampleRetryDelayMs +
        kPumpIntervalMs;
    const int minimumContentSamples =
        std::min(requestedMs, elapsedMs) >= contentCoverageWindowMs ? 2 : 1;
    verdict_.require(samplesTaken_ >= minimumContentSamples,
                     QStringLiteral("at least %1 valid content-hash sample(s) were captured "
                                    "(observed %2)")
                         .arg(minimumContentSamples)
                         .arg(samplesTaken_));

    // (b) every recorded segment delta must fit the budget. A counter the core
    // never reported is an instrumentation gap, never a measured zero - the
    // same distinction the smoke makes when it prints "unavailable (named
    // core limitation, not a measured zero)".
    bool anyDecoderRead = false;
    bool anyVoRead = false;
    for (const DropDelta& delta : dropDeltas_) {
        verdict_.require(delta.decoder.has_value(),
                         QStringLiteral("segment %1 had a decoder-drop baseline and final read")
                             .arg(delta.segment));
        verdict_.require(delta.vo.has_value(),
                         QStringLiteral("segment %1 had a vo-drop baseline and final read")
                             .arg(delta.segment));
        if (delta.decoder.has_value()) {
            anyDecoderRead = true;
            verdict_.require(*delta.decoder >= 0 && *delta.decoder <= options_.maxDrops,
                             QStringLiteral("segment %1 decoder drop delta %2 is non-negative "
                                            "and within the budget of %3")
                                 .arg(delta.segment)
                                 .arg(static_cast<long long>(*delta.decoder))
                                 .arg(options_.maxDrops));
        }
        if (delta.vo.has_value()) {
            anyVoRead = true;
            verdict_.require(*delta.vo >= 0 && *delta.vo <= options_.maxDrops,
                             QStringLiteral("segment %1 vo drop delta %2 is non-negative "
                                            "and within the budget of %3")
                                 .arg(delta.segment)
                                 .arg(static_cast<long long>(*delta.vo))
                                 .arg(options_.maxDrops));
        }
    }
    // Presence is a requirement, not an instrumentation note: a soak whose
    // drop counters were never read has asserted nothing on its drop budget,
    // and a green run of that shape would be a vacuous pass (T-401/T-210).
    verdict_.require(anyDecoderRead,
                     QStringLiteral("decoder-frame-drop-count was read at least once"));
    verdict_.require(anyVoRead,
                     QStringLiteral("frame-drop-count was read at least once"));
    if (options_.requireAudio) {
        verdict_.require(audioTrackId_ > 0 && audioSampleRate_ > 0 && audioClockSamples_ > 0 &&
                             audioPtsProgressed_,
                         QStringLiteral("a selected mpv audio track, valid audio PTS, and audio-PTS "
                                        "progress were observed"));
    }

    verdict_.metric(QStringLiteral("%1 segment(s), %2 content sample(s), %3 frozen-hash "
                                    "failure(s), %4 media error(s)")
                        .arg(segmentIndex_ + 1)
                        .arg(samplesTaken_)
                        .arg(frozenHashFailures_)
                        .arg(mediaErrorCount_));
    if (options_.naturalMedia) {
        verdict_.metric(QStringLiteral(
            "barcode capability: unavailable (natural media has no authored frame identity; "
            "barcode/order assertions disabled)"));
    } else {
        verdict_.metric(QStringLiteral("%1 per-paint barcode readbacks; mean %2 us, maximum %3 us")
                            .arg(static_cast<qulonglong>(identityReadbacks_))
                            .arg(identityReadbacks_ == 0
                                     ? 0.0
                                     : static_cast<double>(readbackTotalUs_) / identityReadbacks_,
                                 0, 'f', 1)
                            .arg(static_cast<qulonglong>(readbackMaxUs_)));
    }
    if (options_.naturalMedia && !options_.frameTimingLog.isEmpty()) {
        verdict_.metric(QStringLiteral(
                            "%1 center-pixel observations; %2 low-luma samples (diagnostic only; "
                            "black frames/cuts are not failures)")
                            .arg(static_cast<qulonglong>(naturalCenterReadbacks_))
                            .arg(static_cast<qulonglong>(naturalBlackSamples_)));
    } else if (options_.naturalMedia) {
        verdict_.metric(QStringLiteral(
            "center-pixel diagnostic disabled (requires --frame-timing-log)"));
    }
    verdict_.metric(QStringLiteral("maximum inter-swap gap: %1 ms")
                        .arg(maxInterSwapGapMs_));
    verdict_.metric(QStringLiteral("rendered frames this segment: %1 (+%2 since baseline)")
                        .arg(static_cast<qulonglong>(segment_.lastRendered))
                        .arg(static_cast<qulonglong>(segment_.lastRendered -
                                                     segment_.renderedBaseline)));
    if (diagnostics.estimatedVfFps.has_value()) {
        verdict_.metric(QStringLiteral("estimated-vf-fps at close: %1")
                            .arg(*diagnostics.estimatedVfFps, 0, 'f', 3));
    }

    if (timingLog_) {
        verdict_.require(!timingLogFailed_,
                         QStringLiteral("timing evidence writes completed without loss"));
        if (!timingLogFailed_) {
            const QByteArray summary =
                QStringLiteral("soak_end elapsed_ms=%1 identity_readbacks=%2 "
                               "readback_total_us=%3 readback_max_us=%4\n")
                    .arg(elapsedMs)
                    .arg(static_cast<qulonglong>(identityReadbacks_))
                    .arg(static_cast<qulonglong>(readbackTotalUs_))
                    .arg(static_cast<qulonglong>(readbackMaxUs_))
                    .toUtf8();
            if (timingLog_->write(summary) != summary.size()) {
                timingLogFailed_ = true;
            }
        }
        if (!timingLog_->flush() || timingLog_->error() != QFileDevice::NoError) {
            timingLogFailed_ = true;
        }
        verdict_.require(!timingLogFailed_,
                         QStringLiteral("timing evidence summary was completely written and flushed"));
        timingLog_->close();
        timingLogClosed_ = true;
    }
    if (!options_.artifactsDirectory.isEmpty()) {
        QWindow* const window = surface_.windowHandle();
        QScreen* const screen = window != nullptr ? window->screen() : nullptr;
        if (window != nullptr && screen != nullptr) {
            screenArtifactFrame_ = screen->grabWindow(window->winId()).toImage();
        }
        screenCaptureUnavailable_ = screenArtifactFrame_.isNull();
        verdict_.metric(screenCaptureUnavailable_
                            ? QStringLiteral("composited-screen capture unavailable: QScreen "
                                             "desktop capture instrumentation limit")
                            : QStringLiteral("composited-screen capture returned actual pixels"));
    }
    surface_.hide();
    surface_.close();
    if (!options_.artifactsDirectory.isEmpty()) {
        const QString firstPath = QDir(options_.artifactsDirectory).filePath(
            QStringLiteral("first-frame.png"));
        const QString lastPath = QDir(options_.artifactsDirectory).filePath(
            QStringLiteral("last-frame.png"));
        const QString screenPath = QDir(options_.artifactsDirectory).filePath(
            QStringLiteral("composited-screen.png"));
        const bool firstSaved = !firstArtifactFrame_.isNull() &&
                                firstArtifactFrame_.save(firstPath, "PNG");
        const bool lastSaved = !lastArtifactFrame_.isNull() &&
                               lastArtifactFrame_.save(lastPath, "PNG");
        const bool screenSaved = !screenCaptureUnavailable_ &&
                                 screenArtifactFrame_.save(screenPath, "PNG");
        artifactWriteFailed_ = !firstSaved || !lastSaved || !screenSaved;
        if (artifactWriteFailed_) {
            const QString failedPath =
                !firstSaved ? firstPath : !lastSaved ? lastPath : screenPath;
            std::fprintf(stderr, "frame_order_soak: cannot save requested PNG evidence %s%s\n",
                         qPrintable(failedPath),
                         screenCaptureUnavailable_ && failedPath == screenPath
                             ? " (desktop capture unavailable)"
                             : "");
        }
        verdict_.require(!artifactWriteFailed_,
                         QStringLiteral("first/last framebuffer and composited-screen PNGs "
                                        "were captured and saved"));
    }
    app_.exit(verdict_.report("frame_order_soak_probe"));
}

void Soak::tick() {
    if (finished_) return;
    qint64 nowMs = wall_.elapsed();
    const mplayer::PlaybackDiagnostics diagnostics = surface_.playbackDiagnostics();
    const bool playing = surface_.hasVideo() && surface_.isPlaying() && !surface_.pauseObserved();

    recordTimingLine(QStringLiteral("tick elapsed_ms=%1 position=%2 rendered=%3 "
                                    "decoder_drops=%4 vo_drops=%5 playing=%6")
                         .arg(nowMs)
                         .arg(surface_.position(), 0, 'f', 3)
                         .arg(static_cast<qulonglong>(diagnostics.renderedOutputFrames))
                         .arg(diagnostics.decoderDropCount.has_value()
                                  ? QString::number(
                                        static_cast<long long>(*diagnostics.decoderDropCount))
                                  : QStringLiteral("unavailable"))
                         .arg(diagnostics.voDropCount.has_value()
                                  ? QString::number(static_cast<long long>(
                                        *diagnostics.voDropCount))
                                  : QStringLiteral("unavailable"))
                         .arg(int(playing)));

    if (!playing) {
        if (segment_.videoSeen && !reopenQueued_) {
            if (notPlayingSinceMs_ < 0) notPlayingSinceMs_ = nowMs;
            if (nowMs - notPlayingSinceMs_ > kMaxFrameGapMs) {
                failAndFinish(QStringLiteral("segment %1 stopped playing for %2 s")
                           .arg(segmentIndex_)
                           .arg((nowMs - notPlayingSinceMs_) / 1000.0, 0, 'f', 1));
            }
        } else if (!segment_.videoSeen && !reopenQueued_ &&
                   segmentStartClock_.elapsed() > kSegmentStartupGraceMs) {
            failAndFinish(QStringLiteral("segment %1 produced no playable video within %2 ms")
                       .arg(segmentIndex_)
                       .arg(static_cast<qint64>(kSegmentStartupGraceMs)));
        }
        return;
    }
    notPlayingSinceMs_ = -1;

    if (!startPositionReady_) {
        if (!startSeekIssued_) {
            startSeekIssued_ = true;
            startSeekAtMs_ = nowMs;
            recordTimingLine(QStringLiteral("start_seek requested_s=%1 pre_seek_position_s=%2")
                                 .arg(options_.startSeconds, 0, 'f', 3)
                                 .arg(surface_.position(), 0, 'f', 3));
            surface_.seek(options_.startSeconds);
            return;
        }
        if (nowMs - startSeekAtMs_ > kSegmentStartupGraceMs) {
            failAndFinish(QStringLiteral("the requested start position %1 s was not reached "
                                         "within %2 ms")
                              .arg(options_.startSeconds, 0, 'f', 3)
                              .arg(static_cast<qint64>(kSegmentStartupGraceMs)));
            return;
        }
        const double position = surface_.position();
        if (!std::isfinite(position) || std::abs(position - options_.startSeconds) > 1.5) return;
        actualStartPosition_ = position;
        startPositionReady_ = true;
        wall_.restart();
        segmentStartClock_.restart();
        nextSampleAtMs = 0;
        nextAudioClockSampleAtMs_ = 0;
        nowMs = wall_.elapsed();
        recordTimingLine(QStringLiteral("start_position requested_s=%1 actual_s=%2")
                             .arg(options_.startSeconds, 0, 'f', 3)
                             .arg(actualStartPosition_, 0, 'f', 3));
        armSafetyDeadline();
    }

    if (!segment_.videoSeen) {
        segment_.videoSeen = true;
        segment_.becameLiveAtMs = nowMs;
        if (actualStartPosition_ < 0.0) {
            actualStartPosition_ = surface_.position();
            recordTimingLine(QStringLiteral("start_position requested_s=%1 actual_s=%2")
                                 .arg(options_.startSeconds, 0, 'f', 3)
                                 .arg(actualStartPosition_, 0, 'f', 3));
        }
        segment_.renderedBaseline = diagnostics.renderedOutputFrames;
        segment_.lastRendered = diagnostics.renderedOutputFrames;
        segment_.lastAdvanceAtMs = nowMs;
        segment_.lastSourcePosition = surface_.position();
        segment_.lastSourceProgressAtMs = nowMs;
        segment_.lastIdentityAtMs = nowMs;
        segment_.lastIdentityAdvanceAtMs = nowMs;
        segment_.decoderAtLive = diagnostics.decoderDropCount;
        segment_.voAtLive = diagnostics.voDropCount;
        segment_.lastFrameIdentity = -1;
        std::fprintf(stderr, "segment %d live at %lld ms (position %.3f s)\n", segmentIndex_,
                     static_cast<long long>(nowMs), surface_.position());
    }

    recordDropObservations(diagnostics);

    // The decoded source clock must move independently of the output-frame
    // counter. It is the mpv time-pos value exposed by VideoSurface, not a
    // wall-clock estimate; unexplained rewinds and stalls are failures.
    const double sourcePosition = surface_.position();
    sampleAudioClock(nowMs);
    if (!std::isfinite(sourcePosition) || sourcePosition < 0.0) {
        verdict_.require(false, QStringLiteral("mpv source time-pos is unavailable while playing"));
    } else if (segment_.lastSourcePosition >= 0.0) {
        if (sourcePosition + 0.75 < segment_.lastSourcePosition) {
            verdict_.require(false,
                             QStringLiteral("mpv source clock moved backwards in segment %1 "
                                            "(%2 s -> %3 s)")
                                 .arg(segmentIndex_)
                                 .arg(segment_.lastSourcePosition, 0, 'f', 3)
                                 .arg(sourcePosition, 0, 'f', 3));
            segment_.lastSourcePosition = sourcePosition;
            segment_.lastSourceProgressAtMs = nowMs;
        } else if (sourcePosition > segment_.lastSourcePosition + 0.02) {
            segment_.lastSourcePosition = sourcePosition;
            segment_.lastSourceProgressAtMs = nowMs;
        } else if (nowMs - segment_.lastSourceProgressAtMs > kMaxFrameGapMs + 2500) {
            verdict_.require(false,
                             QStringLiteral("mpv source time-pos stalled for %1 s in segment %2 "
                                            "(position %3 s, rendered=%4)")
                                 .arg((nowMs - segment_.lastSourceProgressAtMs) / 1000.0, 0, 'f', 1)
                                 .arg(segmentIndex_)
                                 .arg(sourcePosition, 0, 'f', 3)
                                 .arg(static_cast<qulonglong>(diagnostics.renderedOutputFrames)));
            segment_.lastSourceProgressAtMs = nowMs;
        }
    }

    // (a) monotonic, roughly-linear frame growth. A decrease is a context or
    // source reset (the render counter does not survive a GL context
    // recreation, as the render-lifecycle smoke documents); it is re-baselined
    // and reported rather than treated as progress or as a failure.
    if (diagnostics.renderedOutputFrames < segment_.lastRendered) {
        if (options_.noLoop) {
            failAndFinish(QStringLiteral("continuous-source acceptance observed a rendered-frame counter "
                                  "reset/context recreation (%1 -> %2)")
                       .arg(static_cast<qulonglong>(segment_.lastRendered))
                       .arg(static_cast<qulonglong>(diagnostics.renderedOutputFrames)));
            return;
        }
        verdict_.metric(QStringLiteral("the rendered-frame counter reset mid-segment (%1 -> %2); "
                                       "re-baselining, the drop baselines with it")
                            .arg(static_cast<qulonglong>(segment_.lastRendered))
                            .arg(static_cast<qulonglong>(diagnostics.renderedOutputFrames)));
        segment_.renderedBaseline = diagnostics.renderedOutputFrames;
        segment_.lastRendered = diagnostics.renderedOutputFrames;
        segment_.lastAdvanceAtMs = nowMs;
        segment_.decoderAtLive = diagnostics.decoderDropCount;
        segment_.voAtLive = diagnostics.voDropCount;
    } else if (diagnostics.renderedOutputFrames > segment_.lastRendered) {
        segment_.lastRendered = diagnostics.renderedOutputFrames;
        segment_.lastAdvanceAtMs = nowMs;
    }

    // The gap rule. One requirement is recorded per stall (the timestamp is
    // reset with the failure) so a single long stall cannot flood the verdict.
    if (nowMs - segment_.lastAdvanceAtMs > kMaxFrameGapMs) {
        verdict_.require(false,
                         QStringLiteral("no new output frames for %1 s while playing (segment "
                                        "%2, rendered=%3, position %4 s)")
                             .arg((nowMs - segment_.lastAdvanceAtMs) / 1000.0, 0, 'f', 1)
                             .arg(segmentIndex_)
                             .arg(static_cast<qulonglong>(segment_.lastRendered))
                             .arg(surface_.position(), 0, 'f', 3));
        segment_.lastAdvanceAtMs = nowMs;
    }

    if (sampleRetryPending_) {
        if (nowMs >= sampleRetryAtMs) requestContentSample(true);
        return;
    }
    if (nowMs >= nextSampleAtMs) requestContentSample(false);
}

int Soak::run() {
    wall_.start();
    segmentStartClock_.start();

    if (!options_.frameTimingLog.isEmpty()) {
        // Refuse before minutes are spent: a soak whose evidence cannot be
        // written must fail at once, not after half an hour.
        mplayer::VideoSurface::setFrameTimingLogPath(options_.frameTimingLog);
        const QString observationPath = options_.frameTimingLog + QStringLiteral(".probe");
        timingLog_ = std::make_unique<QFile>(observationPath);
        if (!timingLog_->open(QIODevice::WriteOnly | QIODevice::Truncate)) {
            std::fprintf(stderr, "frame_order_soak: cannot open probe observation log %s (%s)\n",
                         qPrintable(observationPath),
                         qPrintable(timingLog_->errorString()));
            return 2;
        }
        const QString hdrPolicyName =
            options_.hdrPolicy == mplayer::VideoSurface::HdrToneMappingPolicy::Stable
                ? QStringLiteral("stable")
                : options_.hdrPolicy == mplayer::VideoSurface::HdrToneMappingPolicy::Vivid
                      ? QStringLiteral("vivid")
                      : QStringLiteral("auto");
        recordTimingLine(QStringLiteral("frame_order_soak media=%1 minutes=%2 start_s=%3 "
                                        "max_drops=%4 sample_interval_s=%5 no_loop=%6 "
                                        "natural_media=%7 barcode_order=%8 hdr_policy=%9 "
                                        "fullscreen=%10 require_audio=%11")
                             .arg(options_.media)
                             .arg(options_.minutes, 0, 'f', 1)
                             .arg(options_.startSeconds, 0, 'f', 3)
                             .arg(options_.maxDrops)
                             .arg(options_.sampleIntervalSeconds)
                             .arg(int(options_.noLoop))
                             .arg(int(options_.naturalMedia))
                             .arg(options_.naturalMedia ? QStringLiteral("unavailable")
                                                        : QStringLiteral("enabled"))
                             .arg(hdrPolicyName)
                             .arg(int(options_.fullscreen))
                             .arg(int(options_.requireAudio)));
    }

    surface_.afterPaint = [this]() { onSurfacePainted(); };
    surface_.setWindowFlag(Qt::WindowStaysOnTopHint, true);
    surface_.setWindowTitle(QStringLiteral("frame_order_soak_probe"));
    surface_.resize(854, 480);
    if (options_.fullscreen) {
        surface_.showFullScreen();
    } else {
        surface_.show();
    }

    QObject::connect(&surface_, &mplayer::VideoSurface::errorOccurred, &surface_,
                     [this](const QString& message) {
                         if (finished_) return;
                         mediaError_ = message;
                         ++mediaErrorCount_;
                         std::fprintf(stderr, "media error: %s\n", qPrintable(message));
                     });

    // The stream-stats mirror and the core's own FPS estimate are recorded as
    // evidence for the timing log; the soak asserts on drop counters and
    // content hashes, which are the signatures a frame-order regression
    // actually leaves.
    QObject::connect(&surface_, &mplayer::VideoSurface::streamStatsChanged, &surface_,
                     [this](double bytesPerSecond, double framesPerSecond,
                            mplayer::StreamFpsSource source) {
                         const char* provenance =
                             source == mplayer::StreamFpsSource::MpvOutput
                                 ? "mpv output"
                                 : source == mplayer::StreamFpsSource::Container
                                       ? "container source"
                                       : "unknown";
                         recordTimingLine(QStringLiteral("stream_stats bytes_per_second=%1 "
                                                          "frames_per_second=%2 (%3)")
                                              .arg(bytesPerSecond, 0, 'f', 1)
                                              .arg(framesPerSecond, 0, 'f', 3)
                                              .arg(QString::fromLatin1(provenance)));
                     });

    QObject::connect(&surface_, &mplayer::VideoSurface::mediaEnded, &surface_,
                     [this]() { onMediaEnded(); });
    QObject::connect(&surface_, &QOpenGLWidget::frameSwapped, &surface_,
                     [this]() { onFrameSwapped(); });

    if (!surface_.open(options_.media)) {
        std::fprintf(stderr, "frame_order_soak: open refused %s\n", qPrintable(options_.media));
        return 2;
    }
    surface_.setMuted(true);
    nextSampleAtMs = 0;

    pump_.setInterval(kPumpIntervalMs);
    QObject::connect(&pump_, &QTimer::timeout, &surface_, [this]() {
        if (finished_) return;
        pollContentHash();
        if (finished_) return;
        const qint64 nowMs = wall_.elapsed();
        if (reopenQueued_) {
            reopenQueued_ = false;
            ++segmentIndex_;
            segment_ = SegmentAccounting{};
            hasIdentityRenderSerial_ = false;
            lastIdentityCaptureSerial_ = 0;
            lastIdentityRenderSerial_ = 0;
            cachedBarcodeRead_ = false;
            contentCaptureRequested_ = false;
            if (!contentHashFuture_.valid()) contentSampleInFlight_ = false;
            pendingContentFrame_ = {};
            segmentStartClock_.start();
            // The new segment starts a fresh content sequence: the last frame
            // before EOF and the first frame after the reopen are not a pair
            // the "content advanced" assertion is allowed to compare.
            previousHash_.clear();
            sampleRetryPending_ = false;
            recordTimingLine(QStringLiteral("segment_start segment=%1 elapsed_ms=%2")
                                 .arg(segmentIndex_)
                                 .arg(nowMs));
            if (!surface_.open(options_.media)) {
                failAndFinish(QStringLiteral("reopening the source for segment %1 was refused")
                           .arg(segmentIndex_));
                return;
            }
        }
        tick();
        if (startPositionReady_ && !finished_ &&
            wall_.elapsed() >= static_cast<qint64>(options_.minutes * 60.0 * 1000.0)) {
            finish();
        }
    });
    pump_.start();

    startPositionReady_ = options_.startSeconds == 0.0;
    if (startPositionReady_) armSafetyDeadline();

    return app_.exec();
}

}  // namespace

int main(int argc, char** argv) {
    QCoreApplication::setAttribute(Qt::AA_UseDesktopOpenGL);
    QApplication app(argc, argv);
    app.setQuitOnLastWindowClosed(false);
    if (!mplayer::probes::selectRuntime()) {
        return 2;
    }

    QCommandLineParser parser;
    parser.setApplicationDescription(
        QStringLiteral("Long-soak frame-order/pacing regression probe (T-401/T-210)"));
    parser.addHelpOption();
    QCommandLineOption mediaOpt(
        QStringLiteral("media"),
        QStringLiteral("media URL or file to soak; a finite clip is replayed until the runtime "
                       "elapses"),
        QStringLiteral("path"));
    parser.addOption(mediaOpt);
    QCommandLineOption minutesOpt(QStringLiteral("minutes"),
                                  QStringLiteral("soak length in minutes (default 30, capped at "
                                                 "1440)"),
                                  QStringLiteral("n"));
    parser.addOption(minutesOpt);
    QCommandLineOption startOpt(QStringLiteral("start"),
                                QStringLiteral("initial source position in seconds (default 0)"),
                                QStringLiteral("seconds"));
    parser.addOption(startOpt);
    QCommandLineOption timingLogOpt(
        QStringLiteral("frame-timing-log"),
        QStringLiteral("write this probe's own tick and sample records to this file"),
        QStringLiteral("file"));
    parser.addOption(timingLogOpt);
    QCommandLineOption maxDropsOpt(QStringLiteral("max-drops"),
                                   QStringLiteral("per-segment drop-counter budget, decoder and "
                                                  "vo (default 3)"),
                                   QStringLiteral("n"));
    parser.addOption(maxDropsOpt);
    QCommandLineOption sampleIntervalOpt(
        QStringLiteral("sample-interval"),
        QStringLiteral("seconds between frame-content hash samples (default 30)"),
        QStringLiteral("seconds"));
    parser.addOption(sampleIntervalOpt);
    QCommandLineOption noLoopOpt(
        QStringLiteral("no-loop"),
        QStringLiteral("fail if the source reaches EOF; use for continuous-source acceptance"));
    parser.addOption(noLoopOpt);
    QCommandLineOption fullscreenOpt(
        QStringLiteral("fullscreen"),
        QStringLiteral("show the probe window fullscreen; default remains 854x480"));
    parser.addOption(fullscreenOpt);
    QCommandLineOption hdrPolicyOpt(
        QStringLiteral("hdr-policy"),
        QStringLiteral("HDR tone-mapping policy applied before surface creation (auto, stable, "
                       "or vivid; default auto)"),
        QStringLiteral("policy"));
    parser.addOption(hdrPolicyOpt);
    QCommandLineOption naturalMediaOpt(
        QStringLiteral("natural-media"),
        QStringLiteral("natural footage has no authored barcode: disable only synthetic barcode "
                       "identity/order assertions"));
    parser.addOption(naturalMediaOpt);
    QCommandLineOption requireAudioOpt(
        QStringLiteral("require-audio"),
        QStringLiteral("require an audio track and compare audio-pts with mpv time-pos"));
    parser.addOption(requireAudioOpt);
    QCommandLineOption artifactsOpt(
        QStringLiteral("artifacts"),
        QStringLiteral("save first and last sampled framebuffer PNGs in this directory"),
        QStringLiteral("directory"));
    parser.addOption(artifactsOpt);
    parser.process(app);

    Options options;
    if (!parser.isSet(mediaOpt)) {
        std::fprintf(stderr,
                     "frame_order_soak: --media is required (nothing else defines the soak's "
                     "subject)\n");
        return 2;
    }
    options.media = parser.value(mediaOpt);
    if (parser.isSet(startOpt)) {
        bool numeric = false;
        const double parsed = parser.value(startOpt).toDouble(&numeric);
        if (!numeric || !std::isfinite(parsed) || parsed < 0.0) {
            std::fprintf(stderr, "frame_order_soak: --start needs a finite non-negative number\n");
            return 2;
        }
        options.startSeconds = parsed;
    }
    if (parser.isSet(minutesOpt)) {
        bool numeric = false;
        const double parsed = parser.value(minutesOpt).toDouble(&numeric);
        if (!numeric || !std::isfinite(parsed) || parsed <= 0.0) {
            std::fprintf(stderr, "frame_order_soak: --minutes needs a positive number\n");
            return 2;
        }
        if (parsed > kMaxMinutes) {
            std::fprintf(stderr, "frame_order_soak: --minutes clamped from %s to %s\n",
                         qPrintable(QString::number(parsed, 'f', 1)),
                         qPrintable(QString::number(kMaxMinutes, 'f', 0)));
            options.minutes = kMaxMinutes;
        } else {
            options.minutes = parsed;
        }
    }
    if (parser.isSet(maxDropsOpt)) {
        bool numeric = false;
        const int parsed = parser.value(maxDropsOpt).toInt(&numeric);
        if (!numeric || parsed < 0) {
            std::fprintf(stderr, "frame_order_soak: --max-drops needs a non-negative integer\n");
            return 2;
        }
        options.maxDrops = parsed;
    }
    if (parser.isSet(sampleIntervalOpt)) {
        bool numeric = false;
        const int parsed = parser.value(sampleIntervalOpt).toInt(&numeric);
        if (!numeric || parsed < 1) {
            std::fprintf(stderr,
                         "frame_order_soak: --sample-interval needs a positive integer of "
                         "seconds\n");
            return 2;
        }
        options.sampleIntervalSeconds = parsed;
    }
    if (parser.isSet(timingLogOpt)) {
        options.frameTimingLog = parser.value(timingLogOpt);
    }
    if (parser.isSet(artifactsOpt)) {
        options.artifactsDirectory = parser.value(artifactsOpt);
        if (options.artifactsDirectory.isEmpty() ||
            !QDir().mkpath(options.artifactsDirectory)) {
            std::fprintf(stderr, "frame_order_soak: cannot create artifacts directory %s\n",
                         qPrintable(options.artifactsDirectory));
            return 2;
        }
    }
    options.noLoop = parser.isSet(noLoopOpt);
    options.naturalMedia = parser.isSet(naturalMediaOpt);
    options.fullscreen = parser.isSet(fullscreenOpt);
    if (parser.isSet(hdrPolicyOpt)) {
        const QString policy = parser.value(hdrPolicyOpt).toLower();
        if (policy == QStringLiteral("auto")) {
            options.hdrPolicy = mplayer::VideoSurface::HdrToneMappingPolicy::Auto;
        } else if (policy == QStringLiteral("stable")) {
            options.hdrPolicy = mplayer::VideoSurface::HdrToneMappingPolicy::Stable;
        } else if (policy == QStringLiteral("vivid")) {
            options.hdrPolicy = mplayer::VideoSurface::HdrToneMappingPolicy::Vivid;
        } else {
            std::fprintf(stderr,
                         "frame_order_soak: --hdr-policy must be auto, stable, or vivid\n");
            return 2;
        }
    }
    options.requireAudio = parser.isSet(requireAudioOpt);

    const char* hdrPolicyName =
        options.hdrPolicy == mplayer::VideoSurface::HdrToneMappingPolicy::Stable
            ? "stable"
            : options.hdrPolicy == mplayer::VideoSurface::HdrToneMappingPolicy::Vivid ? "vivid"
                                                                                     : "auto";
    std::fprintf(stderr, "frame_order_soak: media=%s minutes=%s start=%s max-drops=%d "
                         "sample-interval=%ds no-loop=%d natural-media=%d barcode-order=%s "
                         "hdr-policy=%s fullscreen=%d require-audio=%d\n",
                 qPrintable(options.media),
                 qPrintable(QString::number(options.minutes, 'f', 1)),
                 qPrintable(QString::number(options.startSeconds, 'f', 3)), options.maxDrops,
                 options.sampleIntervalSeconds, int(options.noLoop), int(options.naturalMedia),
                 options.naturalMedia ? "unavailable" : "enabled", hdrPolicyName,
                 int(options.fullscreen), int(options.requireAudio));

    mplayer::VideoSurface::setHdrToneMappingPolicy(options.hdrPolicy);
    Soak soak(options, app);
    return soak.run();
}
